-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function ()
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function()
    hl.exec_cmd("waybar")
    hl.exec_cmd("LC_ALL=es_ES.UTF-8 LANGUAGE=es_ES:es nm-applet --indicator")
    hl.exec_cmd("LC_ALL=es_ES.UTF-8 LANGUAGE=es_ES:es blueman-applet")
    hl.exec_cmd("swaync")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("udiskie --tray --automount")
    hl.exec_cmd("systemctl --user start volume-feedback.service")
    hl.exec_cmd("EMOJI_PICKER_LANGUAGE=es __DOTFILES_HOME__/.local/bin/emoji-picker --daemon")
    hl.exec_cmd("__DOTFILES_HOME__/.config/waybar/scripts/quick-settings.py --daemon")
end)

-- Eleva la ventana enfocada dentro de la pila flotante. Las ventanas tiled
-- conservan el mosaico y destacan mediante active_opacity/dim_inactive.
hl.on("window.active", function(window, _focus_reason)
    if window ~= nil and window.floating then
        pcall(function()
            hl.dispatch(hl.dsp.window.alter_zorder({
                window = window,
                mode = "top",
            }))
        end)
    end
end)

