---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
-- Selector de ventanas: cambia el foco con cada Tab y se cierra al soltar Alt.
hl.bind("ALT + TAB", hl.dsp.exec_cmd("__DOTFILES_HOME__/.config/rofi/alt-tab.sh"))
hl.bind("ALT + SHIFT + TAB", hl.dsp.exec_cmd("__DOTFILES_HOME__/.config/rofi/alt-tab.sh --reverse"))
hl.bind("ALT + ALT_L", hl.dsp.exec_cmd("__DOTFILES_HOME__/.config/rofi/alt-tab.sh --close"), { release = true })
hl.bind("ALT + ALT_R", hl.dsp.exec_cmd("__DOTFILES_HOME__/.config/rofi/alt-tab.sh --close"), { release = true })

-- Cerrar el selector en la liberación física de Alt. El evento nativo evita
-- depender del foco de teclado de la capa visual.
hl.on("input.keyboard.key", function(keycode, _timestamp, state)
    if state == 0 and (keycode == 64 or keycode == 108) then
        hl.exec_cmd("__DOTFILES_HOME__/.config/rofi/alt-tab.sh --close")
    end
end)

hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + W", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("swaync-client -t -sw"))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + period ", hl.dsp.exec_cmd(
    "EMOJI_PICKER_LANGUAGE=es __DOTFILES_HOME__/.local/bin/emoji-picker-show"
))

-- =========================
-- Capturas de pantalla
-- =========================

local screenshotsDir = "$HOME/Imágenes/Capturas\\ de\\ pantalla"

-- Captura de una región y abrirla en Swappy
hl.bind("SUPER + SHIFT + S",
    hl.dsp.exec_cmd(
        "mkdir -p " .. screenshotsDir ..
        " && grim -g \"$(slurp)\" - | swappy -f -"
    )
)

-- Captura de pantalla completa:
-- guardar en Imágenes/Capturas de pantalla + copiar al portapapeles
hl.bind("PRINT",
    hl.dsp.exec_cmd(
        "mkdir -p " .. screenshotsDir ..
        " && FILE=\"$HOME/Imágenes/Capturas de pantalla/Captura de pantalla $(date '+%Y-%m-%d %H-%M-%S').png\"" ..
        " && grim \"$FILE\"" ..
        " && wl-copy < \"$FILE\"" ..
        " && notify-send \"Captura de pantalla\" \"Captura guardada correctamente\""
    )
)

-- Captura de región:
-- guardar + copiar al portapapeles
hl.bind("SHIFT + PRINT",
    hl.dsp.exec_cmd(
        "mkdir -p " .. screenshotsDir ..
        " && GEOMETRY=\"$(slurp)\"" ..
        " && [ -n \"$GEOMETRY\" ]" ..
        " && FILE=\"$HOME/Imágenes/Capturas de pantalla/Captura de pantalla $(date '+%Y-%m-%d %H-%M-%S').png\"" ..
        " && grim -g \"$GEOMETRY\" \"$FILE\"" ..
        " && wl-copy < \"$FILE\"" ..
        " && notify-send \"Captura de pantalla\" \"Selección guardada correctamente\""
    )
)

-- =========================
-- Portapapeles
-- =========================

hl.bind(mainMod .. " + V",
    hl.dsp.exec_cmd(
        "cliphist list | rofi -dmenu -p 'Portapapeles' | cliphist decode | wl-copy"
    )
)

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + H",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


